insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0003-0000-4000-8000-000000000014', 'en', null, 'Corporate Finance', 'How firms raise money, choose which projects to fund, and value what they own — time value of money, discounted cash flow, risk and return, the cost of capital, capital structure, and valuation. Structure adapted from OpenStax Principles of Finance (CC BY 4.0).', null, 'career', 20, true, 'business', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0003-0000-4000-8000-000000000014', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"A dollar received today is worth more than a dollar received next year mainly because…","options":["prices always fall over time","today''s dollar can be invested to earn a return","banks charge fees on future dollars","future dollars are counterfeit"],"answer":1,"explanation":"That is the time value of money — money in hand can be put to work and grow, so a future dollar must be discounted back to compare fairly."},{"prompt":"If a project''s net present value (NPV) is positive at the firm''s required return, the basic decision rule says…","options":["reject it","accept it","wait ten years","borrow more first"],"answer":1,"explanation":"A positive NPV means the discounted inflows exceed the cost, so the project adds value — accept it."},{"prompt":"The present value of a single cash flow FV received in n years at rate r is…","options":["FV * (1+r)^n","FV / (1+r)^n","FV * n * r","FV / (n*r)"],"answer":1,"explanation":"Discounting divides by (1+r)^n: PV = FV / (1+r)^n."},{"prompt":"Holding a mix of assets whose returns do not move together mainly reduces…","options":["the risk-free rate","diversifiable (firm-specific) risk","the tax rate","the coupon on a bond"],"answer":1,"explanation":"Diversification averages away firm-specific ups and downs; only market-wide (systematic) risk remains."},{"prompt":"The weighted average cost of capital (WACC) blends the costs of…","options":["inventory and receivables","debt and equity","fixed and variable costs","revenue and profit"],"answer":1,"explanation":"WACC weights the after-tax cost of debt and the cost of equity by their share of total financing — see ''Cost of capital''."},{"prompt":"Compared with equity, debt financing is usually cheaper partly because…","options":["interest is tax-deductible","lenders never expect repayment","shares pay no dividends","debt has no risk"],"answer":0,"explanation":"Interest expense reduces taxable income, creating a tax shield, and debtholders bear less risk than shareholders, so they accept a lower rate."},{"prompt":"When a bond''s market yield rises above its coupon rate, the bond''s price will…","options":["rise above face value","fall below face value","stay exactly at face value","double"],"answer":1,"explanation":"Price and yield move in opposite directions; a yield above the coupon means the bond trades at a discount to face value."},{"prompt":"Net working capital is defined as…","options":["total assets minus total debt","current assets minus current liabilities","revenue minus expenses","cash minus dividends"],"answer":1,"explanation":"Working capital is the short-term cushion: current assets minus current liabilities — see ''Capital structure and working capital''."}]}'::jsonb, null, 10),
  (2, 'What corporate finance is: a financial-statements refresher', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State the three questions corporate finance answers, and read the three core financial statements well enough to pull the numbers later lessons need. Warm-up: from the diagnostic, why is a dollar today worth more than a dollar next year?"},{"heading":"The idea","text":"Corporate finance studies how a firm raises money, invests it, and returns it to owners. Three questions drive everything: (1) Which long-term projects should we fund? (this is capital budgeting) (2) How should we pay for them — debt, equity, or retained earnings? (this is capital structure) (3) How do we manage day-to-day cash? (this is working capital management). To answer them you read three statements. The income statement shows revenue minus expenses over a period, ending in net income. The balance sheet is a snapshot at one instant: assets = liabilities + equity. The cash flow statement tracks actual cash moving in and out, split into operating, investing, and financing activities. Profit on the income statement is not the same as cash, because sales can be booked before the money arrives."},{"heading":"Worked examples","text":"Income statement: revenue 500, cost of goods sold 300, operating expenses 120, so operating income is 500 - 300 - 120 = 80; after interest of 10 and tax of 25 percent, net income is (80 - 10) * (1 - 0.25) = 52.5. Balance sheet check: if assets are 1,000 and liabilities are 600, then equity must be 1,000 - 600 = 400, because assets = liabilities + equity. Cash vs profit: a firm reports net income of 52.5 but its receivables grew by 40 (customers have not paid yet), so cash from operations is closer to 52.5 - 40 = 12.5 before other adjustments. A profitable firm can still run short of cash."},{"heading":"Your turn","text":"1) Revenue 800, COGS 500, operating expenses 200 — what is operating income? 2) If assets are 1,200 and equity is 500, what are liabilities? 3) Which statement would you read to see whether the firm actually collected cash this year? 4) Which of the three finance questions is ''should we build this new plant?'' 5) Name the equation the balance sheet must always satisfy. Answers: 1) 800 - 500 - 200 = 100. 2) 1,200 - 500 = 700. 3) the cash flow statement. 4) capital budgeting. 5) assets = liabilities + equity."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating net income as cash in the bank — accrual accounting records revenue when earned, not when collected. Mistake: forgetting that the balance sheet is one instant while the income statement spans a period. Exit: (a) What are the two sides the balance sheet must balance? (b) Which statement ends in net income? Answers: assets on one side, liabilities plus equity on the other; the income statement."}]}'::jsonb, 'This course teaches methods for analyzing decisions in general; it is education, not personalized financial or investment advice for your own money.', 12),
  (3, 'Time value of money, discounting, and NPV', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Move a cash flow forward with future value, move it backward with present value, and combine several discounted cash flows into a net present value. Warm-up: which is worth more today, 100 dollars now or 100 dollars in three years, and why?"},{"heading":"The idea","text":"Future value grows a sum forward: FV = PV * (1+r)^n, where r is the periodic return and n is the number of periods. Present value runs the movie backward, discounting a future amount to today: PV = FV / (1+r)^n. The factor 1 / (1+r)^n is the discount factor; a higher rate or a longer wait makes it smaller, so distant cash is worth less now. Net present value takes a whole stream of future cash flows CF_1, CF_2, ..., CF_n, discounts each to today, and subtracts the up-front cost: NPV = -CF_0 + CF_1/(1+r)^1 + CF_2/(1+r)^2 + ... + CF_n/(1+r)^n. If NPV is positive, the investment earns more than the required rate r and adds value."},{"heading":"Worked examples","text":"Future value: 1,000 invested at r = 5 percent for 3 years grows to 1,000 * (1.05)^3 = 1,000 * 1.157625 = 1,157.63. Present value: 1,000 due in 2 years at r = 8 percent is worth 1,000 / (1.08)^2 = 1,000 / 1.1664 = 857.34 today. NPV: a project costs 1,000 now and returns 600 at the end of year 1 and 600 at the end of year 2, with r = 10 percent. Discount each inflow: 600 / 1.10 = 545.45 and 600 / (1.10)^2 = 495.87. Their sum is 1,041.32, so NPV = 1,041.32 - 1,000 = 41.32. Positive, so the project clears the 10 percent hurdle."},{"heading":"Your turn","text":"1) What is the future value of 2,000 at 6 percent for 1 year? 2) What is the present value of 5,000 due in 3 years at 10 percent? 3) A project costs 900 now and pays 500 in year 1 and 500 in year 2 at r = 8 percent — is its NPV positive? 4) If the discount rate rises, does present value go up or down? 5) Write the present-value formula in symbols. Answers: 1) 2,000 * 1.06 = 2,120. 2) 5,000 / (1.10)^3 = 5,000 / 1.331 = 3,756.57. 3) 500/1.08 + 500/1.1664 = 462.96 + 428.67 = 891.63; NPV = 891.63 - 900 = -8.37, so slightly negative — reject. 4) down. 5) PV = FV / (1+r)^n."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using simple interest (1 + r*n) instead of compounding (1+r)^n, which understates growth over many periods. Mistake: forgetting to subtract the up-front cost CF_0 when computing NPV. Exit: (a) What is the discount factor for one period at rate r? (b) What decision does a positive NPV support? Answers: 1 / (1+r); accept the project, since it earns more than the required return."}]}'::jsonb, 'Keep the rate and the period on the same clock: an annual rate discounts annual cash flows; write compounding as (1+r)^n, never 1 + r*n.', 15),
  (4, 'Capital budgeting: NPV, IRR, and payback', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Rank investment projects using three tools — net present value, internal rate of return, and payback period — and explain why NPV is the most reliable. Warm-up: if a project''s NPV is exactly zero, what return is it earning relative to the required rate?"},{"heading":"The idea","text":"Capital budgeting decides which long-term projects deserve funding. Net present value (NPV) discounts all cash flows at the required rate r and accepts any project with NPV greater than 0. The internal rate of return (IRR) is the single rate that makes NPV equal to 0; you accept a project when its IRR exceeds the required rate r. The payback period is the time needed to recover the initial outlay from the cash inflows. Payback is simple but ignores the time value of money and everything that happens after payback; IRR can give misleading answers when projects differ in size or when cash flows change sign more than once. NPV, measured in today''s dollars, is the tie-breaker whenever the rules conflict."},{"heading":"Worked examples","text":"A project costs 1,000 now and returns 500 at the end of each of years 1, 2, and 3, with r = 10 percent. Payback: 500 + 500 = 1,000 recovered by the end of year 2, so payback is 2 years. NPV: 500/1.10 + 500/(1.10)^2 + 500/(1.10)^3 = 454.55 + 413.22 + 375.66 = 1,243.43, so NPV = 1,243.43 - 1,000 = 243.43. IRR: the rate that sets NPV to 0 is about 23 percent (testing r = 0.23 leaves NPV near zero), and since 23 percent is above the 10 percent hurdle, IRR agrees with NPV — accept. Contrast: a project with a fast payback but small later cash flows can still have a lower NPV than a slower project, which is why payback alone can mislead."},{"heading":"Your turn","text":"1) A project costs 600 and returns 300 per year for 2 years — what is its payback period? 2) At r = 0, what does NPV reduce to? 3) The IRR rule says accept when IRR is above what? 4) Which method ignores the time value of money? 5) If NPV is positive but payback is ''too long'' by a rule of thumb, which signal should generally win? Answers: 1) 300 + 300 = 600 recovered in exactly 2 years. 2) the simple sum of cash flows minus the cost, since dividing by (1+0)^n does nothing. 3) the required rate of return r (the hurdle rate). 4) the payback period. 5) NPV, because it measures value added in today''s dollars."},{"heading":"Common mistakes & exit ticket","text":"Mistake: choosing the project with the shortest payback regardless of the cash flows that arrive later. Mistake: assuming a higher IRR always means a better project — a small project can have a high IRR but add little total value. Exit: (a) What return does a project with NPV = 0 earn relative to r? (b) Which single rule best measures value added? Answers: exactly the required rate r (its IRR equals r); NPV."}]}'::jsonb, 'When NPV and another rule disagree on which project to pick, trust NPV — it measures value added in today''s dollars, while IRR and payback can mislead.', 15),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The future value of 1,000 invested for 3 years at 5 percent is closest to…","options":["1,150.00","1,157.63","1,015.00","1,050.00"],"answer":1,"explanation":"1,000 * (1.05)^3 = 1,000 * 1.157625 = 1,157.63."},{"prompt":"The present value of 1,000 due in 2 years at 8 percent is closest to…","options":["857.34","925.93","1,166.40","800.00"],"answer":0,"explanation":"1,000 / (1.08)^2 = 1,000 / 1.1664 = 857.34."},{"prompt":"A project costs 1,000 and returns 600 in year 1 and 600 in year 2 at r = 10 percent. Its NPV is closest to…","options":["-41.32","41.32","200.00","1,041.32"],"answer":1,"explanation":"600/1.10 + 600/1.21 = 545.45 + 495.87 = 1,041.32; NPV = 1,041.32 - 1,000 = 41.32."},{"prompt":"The internal rate of return (IRR) is defined as the discount rate that makes NPV equal to…","options":["the initial cost","zero","the required rate","the payback period"],"answer":1,"explanation":"IRR is the rate at which discounted inflows exactly equal the outflow, so NPV = 0."},{"prompt":"Which method ignores the time value of money and everything after the cutoff?","options":["NPV","IRR","payback period","discounted cash flow"],"answer":2,"explanation":"Payback just counts years to recover the cost; it neither discounts nor looks past the recovery point."},{"prompt":"If the discount rate increases, the present value of a fixed future cash flow will…","options":["increase","decrease","stay the same","become negative"],"answer":1,"explanation":"A larger (1+r)^n in the denominator shrinks PV — price of waiting rises."}]}'::jsonb, null, 8),
  (6, 'Risk, return, and the cost of capital', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute an expected return, explain how diversification lowers risk, and build a firm''s weighted average cost of capital (WACC). Warm-up: if two stocks tend to rise and fall at different times, what happens to the swings of a portfolio holding both?"},{"heading":"The idea","text":"Expected return is the probability-weighted average of possible returns: E[R] = p_1*R_1 + p_2*R_2 + ... . Risk is how far actual returns scatter around that average, measured by variance and its square root, the standard deviation (sqrt of variance). Diversification — holding assets whose returns do not move in lockstep — cancels out firm-specific surprises, so a portfolio''s risk is less than the average risk of its parts. What cannot be diversified away is market-wide (systematic) risk, and that is what investors are paid to bear. A firm funds itself with debt and equity, each with its own required return. The weighted average cost of capital blends them: WACC = (E/V)*Re + (D/V)*Rd*(1 - Tc), where E and D are the market values of equity and debt, V = E + D, Re and Rd are their costs, and Tc is the corporate tax rate that makes debt cheaper through its tax shield."},{"heading":"Worked examples","text":"Expected return: a stock returns +20 percent with probability 0.5 and -10 percent with probability 0.5, so E[R] = 0.5*20 + 0.5*(-10) = 5 percent. Diversification: combine that stock with another that tends to zig when the first zags; the portfolio''s standard deviation falls below the simple average of the two, even though the average return does not. WACC: a firm has equity worth 60 and debt worth 40, so V = 100. If Re = 12 percent, Rd = 6 percent, and Tc = 25 percent, then WACC = (60/100)*12 + (40/100)*6*(1 - 0.25) = 7.2 + 1.8 = 9.0 percent. That 9 percent is the hurdle rate for the firm''s average-risk projects."},{"heading":"Your turn","text":"1) A stock pays +30 percent or -10 percent, each with probability 0.5 — what is E[R]? 2) In WACC, what does the term (1 - Tc) adjust and why? 3) Firm has E = 80, D = 20, Re = 10 percent, Rd = 5 percent, Tc = 20 percent — compute WACC. 4) Which kind of risk can diversification NOT remove? 5) What is the standard deviation the square root of? Answers: 1) 0.5*30 + 0.5*(-10) = 10 percent. 2) it lowers the cost of debt to an after-tax figure, because interest is tax-deductible. 3) (0.8)*10 + (0.2)*5*(0.8) = 8 + 0.8 = 8.8 percent. 4) systematic (market-wide) risk. 5) the variance."},{"heading":"Common mistakes & exit ticket","text":"Mistake: using the before-tax cost of debt in WACC and forgetting the (1 - Tc) shield. Mistake: thinking diversification removes all risk — it only removes the firm-specific part. Exit: (a) Write the WACC formula. (b) Which risk are investors compensated for holding? Answers: WACC = (E/V)*Re + (D/V)*Rd*(1 - Tc); systematic (non-diversifiable) risk."}]}'::jsonb, 'Investors are compensated only for risk they cannot diversify away; the after-tax cost of debt uses (1 - tax rate) because interest is deductible.', 15),
  (7, 'Capital structure and working capital management', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Weigh debt against equity, describe how leverage magnifies outcomes, and measure a firm''s short-term liquidity with working capital and the cash conversion cycle. Warm-up: why might a profitable firm still be unable to pay its bills next month?"},{"heading":"The idea","text":"Capital structure is the mix of debt and equity a firm uses. Debt is cheaper — interest is tax-deductible and lenders take less risk — but it adds fixed interest payments that must be met in good times and bad, raising the chance of financial distress. Equity carries no repayment obligation but is more expensive and dilutes ownership. Leverage is the use of debt; it magnifies returns to shareholders when the firm earns more than its borrowing cost, and magnifies losses when it does not. Separately, working capital management keeps the firm solvent day to day. Net working capital = current assets - current liabilities. The cash conversion cycle (CCC) measures how long cash is tied up: CCC = days inventory outstanding (DIO) + days sales outstanding (DSO) - days payables outstanding (DPO). A shorter cycle frees cash."},{"heading":"Worked examples","text":"Leverage: a firm earns 15 percent on its assets. Financed all-equity, owners earn about 15 percent. Financed half with debt costing 6 percent, the equity return rises because cheap debt funds assets earning 15 percent — but if asset returns fell to 3 percent, the fixed 6 percent interest would now drag equity returns below the all-equity case. Working capital: current assets 300, current liabilities 180, so net working capital = 300 - 180 = 120. Cash conversion cycle: DIO = 50 days, DSO = 40 days, DPO = 30 days, so CCC = 50 + 40 - 30 = 60 days — the firm waits 60 days between paying for inputs and collecting from customers."},{"heading":"Your turn","text":"1) Current assets 250, current liabilities 100 — what is net working capital? 2) DIO = 45, DSO = 35, DPO = 20 — what is the cash conversion cycle? 3) Name one advantage and one drawback of financing with debt. 4) Does more leverage make equity returns more or less volatile? 5) Would speeding up customer payments (lower DSO) lengthen or shorten the CCC? Answers: 1) 250 - 100 = 150. 2) 45 + 35 - 20 = 60 days. 3) advantage: interest is tax-deductible and debt is cheaper; drawback: fixed payments raise the risk of distress. 4) more volatile. 5) shorten it."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming more debt is always better because it is cheap — beyond a point the risk of distress raises every cost. Mistake: confusing profit with liquidity; a firm can be profitable yet cash-poor if too much is locked in inventory and receivables. Exit: (a) Write the cash conversion cycle formula. (b) What does leverage do to both gains and losses for shareholders? Answers: CCC = DIO + DSO - DPO; it magnifies them."}]}'::jsonb, 'Leverage cuts both ways: borrowing lifts returns on equity when times are good and deepens losses when they are not — more debt means more fixed obligations.', 14),
  (8, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"A stock returns +20 percent or -10 percent, each with probability 0.5. Its expected return is…","options":["15 percent","5 percent","10 percent","-5 percent"],"answer":1,"explanation":"E[R] = 0.5*20 + 0.5*(-10) = 10 - 5 = 5 percent."},{"prompt":"With E = 60, D = 40, Re = 12 percent, Rd = 6 percent, Tc = 25 percent, WACC equals…","options":["9.0 percent","10.8 percent","7.2 percent","6.0 percent"],"answer":0,"explanation":"(0.6)*12 + (0.4)*6*(0.75) = 7.2 + 1.8 = 9.0 percent."},{"prompt":"The risk that diversification cannot remove is called…","options":["firm-specific risk","systematic (market) risk","credit risk","liquidity risk"],"answer":1,"explanation":"Diversification cancels firm-specific surprises; market-wide systematic risk remains and is what investors are paid to bear."},{"prompt":"Net working capital equals current assets minus…","options":["total liabilities","current liabilities","long-term debt","equity"],"answer":1,"explanation":"Net working capital = current assets - current liabilities, the short-term liquidity cushion."},{"prompt":"With DIO = 50, DSO = 40, DPO = 30, the cash conversion cycle is…","options":["120 days","60 days","20 days","40 days"],"answer":1,"explanation":"CCC = DIO + DSO - DPO = 50 + 40 - 30 = 60 days."},{"prompt":"Adding debt to the capital structure generally makes shareholders'' returns…","options":["less volatile","more volatile","risk-free","unchanged"],"answer":1,"explanation":"Leverage magnifies both gains and losses on equity because interest is a fixed claim paid first."}]}'::jsonb, null, 8),
  (9, 'Valuation and a capstone decision case: bonds and stocks', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Value a bond and a stock from their cash flows, then work a capstone case that ties together NPV, WACC, and financing. Warm-up: if a bond''s yield is higher than its coupon rate, will it trade above or below face value?"},{"heading":"The idea","text":"A bond pays fixed coupons each period plus its face value at maturity. Its price is the present value of those cash flows discounted at the market yield y: Price = C/(1+y)^1 + C/(1+y)^2 + ... + C/(1+y)^n + Face/(1+y)^n. When y is above the coupon rate the bond sells at a discount; when y is below it, at a premium. A stock is valued the same way, as the present value of expected future dividends. The constant-growth (Gordon) model assumes dividends grow at a steady rate g forever: Price = D_1 / (r - g), where D_1 is next year''s dividend and r is the required return (with r greater than g). The whole toolkit reduces to one idea: forecast cash flows, discount at a risk-appropriate rate, and sum."},{"heading":"Worked examples","text":"Bond: face 1,000, annual coupon 5 percent (so C = 50), 3 years, market yield y = 6 percent. Price = 50/1.06 + 50/(1.06)^2 + 50/(1.06)^3 + 1,000/(1.06)^3 = 47.17 + 44.50 + 41.98 + 839.62 = 973.27, a discount because 6 percent exceeds the 5 percent coupon. Stock: next year''s dividend D_1 = 2, required return r = 10 percent, growth g = 3 percent, so Price = 2 / (0.10 - 0.03) = 2 / 0.07 = 28.57. Capstone case: a firm can invest 1,000 today in equipment expected to generate 450 per year for 3 years. Its WACC is 9 percent. NPV = 450/1.09 + 450/(1.09)^2 + 450/(1.09)^3 - 1,000 = 412.84 + 378.75 + 347.48 - 1,000 = 139.07. Because NPV is positive at the firm''s own cost of capital, the project adds value and clears the hurdle."},{"heading":"Your turn","text":"1) A bond with y = 4 percent and a 4 percent coupon trades at, above, or below par? 2) Value a stock with D_1 = 3, r = 12 percent, g = 4 percent. 3) In the capstone case above, what rate was used to discount the equipment''s cash flows, and where did it come from? 4) If the equipment instead cost 1,300, would the NPV still be positive? 5) Why is the same discounting logic used for both bonds and stocks? Answers: 1) at par, because yield equals the coupon. 2) 3 / (0.12 - 0.04) = 3 / 0.08 = 37.50. 3) 9 percent, the firm''s WACC from the cost-of-capital lesson. 4) NPV would be about 1,139.07 - 1,300 = -160.93, so no, negative — reject. 5) both are just streams of future cash flows discounted at a risk-appropriate rate."},{"heading":"Common mistakes & exit ticket","text":"Mistake: discounting a bond''s coupons at the coupon rate instead of the market yield — always discount at y. Mistake: using the Gordon model when g is greater than or equal to r, which makes the formula break down. Exit: (a) Write the constant-growth stock price formula. (b) In the capstone case, what made the 1,000 project acceptable? Answers: Price = D_1 / (r - g) with r greater than g; its NPV was positive at the firm''s WACC of 9 percent."}]}'::jsonb, 'Every valuation is just discounted cash flow: list the future cash a claim pays, discount at the rate that reflects its risk, and add it up. This is analysis practice, not advice to buy or sell any security.', 16),
  (10, 'Comprehensive final', 'quiz', '{"questions":[{"prompt":"The core principle behind discounting is that…","options":["cash flows never change","money available sooner is worth more because it can earn a return","taxes always rise","risk does not affect value"],"answer":1,"explanation":"The time value of money: earlier cash can be reinvested, so later cash must be discounted to compare fairly."},{"prompt":"A project costs 1,000 and returns 500 per year for 3 years at r = 10 percent. Its NPV is closest to…","options":["243","500","-243","1,243"],"answer":0,"explanation":"500/1.10 + 500/1.21 + 500/1.331 = 454.55 + 413.22 + 375.66 = 1,243.43; NPV = 1,243.43 - 1,000 = 243.43."},{"prompt":"When NPV and IRR disagree about which of two projects to choose, the more reliable guide is…","options":["payback period","IRR","NPV","the coupon rate"],"answer":2,"explanation":"NPV measures value added in today''s dollars and does not suffer IRR''s scale and sign-change pitfalls."},{"prompt":"With E = 60, D = 40, Re = 12 percent, Rd = 6 percent, and Tc = 25 percent, the firm''s WACC is…","options":["7.2 percent","9.0 percent","10.8 percent","6.0 percent"],"answer":1,"explanation":"(0.6)*12 + (0.4)*6*(1 - 0.25) = 7.2 + 1.8 = 9.0 percent."},{"prompt":"Diversification reduces which portion of a portfolio''s risk?","options":["systematic (market) risk","firm-specific (diversifiable) risk","the risk-free rate","none of it"],"answer":1,"explanation":"Firm-specific surprises average out across many assets; systematic market risk cannot be diversified away."},{"prompt":"Compared with equity, debt lowers the cost of capital partly because interest is…","options":["paid in shares","tax-deductible","never repaid","risk-free to lenders"],"answer":1,"explanation":"The interest tax shield, captured by the (1 - Tc) term in WACC, makes after-tax debt cheaper."},{"prompt":"A 3-year bond with a 5 percent coupon priced at a market yield of 6 percent will trade…","options":["above face value","at face value","below face value","at zero"],"answer":2,"explanation":"Yield above coupon means the bond is discounted to below par (about 973 on a 1,000 face)."},{"prompt":"Using the constant-growth model with D_1 = 2, r = 10 percent, and g = 3 percent, the stock''s value is closest to…","options":["28.57","20.00","66.67","14.29"],"answer":0,"explanation":"Price = D_1 / (r - g) = 2 / (0.10 - 0.03) = 2 / 0.07 = 28.57."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0003-0000-4000-8000-000000000014' and l.position = v.pos
);
